#include <algorithm>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
#include <zlib.h>
namespace fs=std::filesystem;
static uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}static uint64_t fnv(const std::string&s){uint64_t h=1469598103934665603ULL;for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}static uint32_t p2(uint64_t x){uint64_t p=1;while(p<x)p<<=1;return uint32_t(p);}struct Addr{uint32_t rho;uint64_t fp;};static Addr enc(const std::string&k,uint32_t M){uint64_t h0=mix64(fnv(k)),h1=mix64(h0^0xD6E8FEB86659FD93ULL),h2=mix64(h1^0xA5A35625D3E7E5B9ULL),h3=mix64(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0&(M-1)),mix64(h0^(h1<<1)^(h2>>1)^h3)};}
static size_t rss_kb(){std::ifstream f("/proc/self/status");std::string k;size_t v;std::string u;while(f>>k){if(k=="VmRSS:"){f>>v>>u;return v;}std::getline(f,u);}return 0;}
static uint32_t crc0(const void*p,size_t n){return uint32_t(crc32(0,(const Bytef*)p,n));}static void u32(std::vector<uint8_t>&b,uint32_t v){for(int i=3;i>=0;--i)b.push_back(uint8_t(v>>(8*i)));}static void u64(std::vector<uint8_t>&b,uint64_t v){for(int i=7;i>=0;--i)b.push_back(uint8_t(v>>(8*i)));}static uint32_t be32(const uint8_t*p){return(uint32_t(p[0])<<24)|(uint32_t(p[1])<<16)|(uint32_t(p[2])<<8)|p[3];}static uint64_t be64(const uint8_t*p){uint64_t v=0;for(int i=0;i<8;++i)v=(v<<8)|p[i];return v;}
struct Slot{uint64_t k=0,v=0;uint32_t d=0;uint8_t state=0;};class RH{std::vector<Slot>s;size_t mask=0;public:RH(){}explicit RH(size_t n){reset(n);}void reset(size_t n){size_t c=8;while(double(c)*.72<double(std::max<size_t>(1,n)))c<<=1;s.assign(c,{});mask=c-1;}void put(uint64_t k,uint64_t v){size_t i=mix64(k)&mask;Slot cur{k,v,0,1};for(;;){auto&x=s[i];if(x.state!=1){x=cur;return;}if(x.k==k){x.v=v;return;}if(x.d<cur.d)std::swap(x,cur);i=(i+1)&mask;++cur.d;}}bool get(uint64_t k,uint64_t&v)const{size_t i=mix64(k)&mask;uint32_t d=0;for(;;){const auto&x=s[i];if(x.state==0||x.d<d)return false;if(x.state==1&&x.k==k){v=x.v;return true;}i=(i+1)&mask;++d;}}};
class Index{uint32_t M;std::vector<std::unique_ptr<RH>>p;public:Index(size_t n):M(p2(std::max<uint64_t>(64,(n+255)/256))),p(M){size_t per=(n+M-1)/M+32;for(auto&x:p)x=std::make_unique<RH>(per);}void put(const std::string&k,uint64_t v){auto a=enc(k,M);p[a.rho]->put(a.fp,v);}bool get(const std::string&k,uint64_t&v)const{auto a=enc(k,M);return p[a.rho]->get(a.fp,v);}uint32_t parts()const{return M;}};
static std::vector<uint8_t> make_snapshot(size_t N){std::vector<uint8_t>b;b.insert(b.end(),{'B','D','R','3'});u32(b,3);u64(b,N);u64(b,N);for(size_t i=0;i<N;++i){std::string k="K"+std::to_string(i);u32(b,uint32_t(k.size()));u32(b,8);b.insert(b.end(),k.begin(),k.end());u64(b,i);}u32(b,crc0(b.data(),b.size()));return b;}static void write_snapshot(const fs::path&p,size_t N){auto b=make_snapshot(N);std::ofstream f(p,std::ios::binary|std::ios::trunc);f.write((char*)b.data(),std::streamsize(b.size()));}
static void read_crc(std::ifstream&f,void*buf,size_t n,uLong&c){f.read((char*)buf,std::streamsize(n));if(f.gcount()!=std::streamsize(n))throw std::runtime_error("snapshot truncated");c=crc32(c,(const Bytef*)buf,uInt(n));}
static std::unique_ptr<Index> recover_direct_stream(const fs::path&p,size_t&Nout,uint64_t&seq){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("open snapshot");uLong c=crc32(0L,Z_NULL,0);uint8_t head[24];read_crc(f,head,sizeof(head),c);if(std::memcmp(head,"BDR3",4))throw std::runtime_error("magic");if(be32(head+4)!=3)throw std::runtime_error("version");seq=be64(head+8);uint64_t N=be64(head+16);auto idx=std::make_unique<Index>(N);std::vector<uint8_t>key;for(uint64_t i=0;i<N;++i){uint8_t lens[8];read_crc(f,lens,8,c);uint32_t kl=be32(lens),vl=be32(lens+4);if(vl!=8||kl>(1u<<20))throw std::runtime_error("record bounds");key.resize(kl);if(kl)read_crc(f,key.data(),kl,c);uint8_t vb[8];read_crc(f,vb,8,c);idx->put(std::string((char*)key.data(),key.size()),be64(vb));}uint8_t cb[4];f.read((char*)cb,4);if(f.gcount()!=4)throw std::runtime_error("crc missing");if(uint32_t(c)!=be32(cb))throw std::runtime_error("crc mismatch");if(f.peek()!=std::ifstream::traits_type::eof())throw std::runtime_error("trailing data");Nout=N;return idx;}
int main(int argc,char**argv){size_t N=argc>1?std::stoull(argv[1]):1000000;fs::path p="v40_snapshot.bdr3";write_snapshot(p,N);size_t before=rss_kb(),nr=0;uint64_t seq=0;auto idx=recover_direct_stream(p,nr,seq);size_t after=rss_kb();uint64_t err=0;for(size_t i=0;i<N;i+=997){uint64_t v=~0ull;if(!idx->get("K"+std::to_string(i),v)||v!=i)++err;}bool pass=nr==N&&seq==N&&err==0;std::cout<<"records,partitions,rss_before_kb,rss_after_kb,rss_delta_kb,sequence,errors,pass\n"<<nr<<','<<idx->parts()<<','<<before<<','<<after<<','<<(after>=before?after-before:0)<<','<<seq<<','<<err<<','<<pass<<"\n";return pass?0:2;}
